    #[must_use]
    pub fn render_json(&self) -> String {
        let hints_est: usize = self.hints.iter().map(|h| h.as_str().len() + 4).sum();
        let causes_est: usize = self.causes.iter().map(|c| c.len() + 4).sum();
        let recovery_est: usize = self.recovery.as_ref().map_or(0, |r| {
