/// One section's line in the budget roll-up.
///
/// `#[non_exhaustive]`: build it with [`SectionCost::new`] and the builder methods.
#[derive(Debug, Clone, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize))]
